--region private
function JapaneseStoryStageCell:RefreshUI(cellData, isSelected)
    CfUtils.SetActive(self.NorBg, not isSelected)
    

    if isSelected then
        CfUtils.SetActive(self.ImgBgSelect, isSelected)
        CfUtils.SetUISwitchText(self.TxtDeco, 1)
        CfUtils.SetUISwitchText(self.TextTitle, 1)
    else
        CfUtils.SetActive(self.ImgBgSelect, isSelected)
        CfUtils.SetUISwitchText(self.TxtDeco, 2)
        CfUtils.SetUISwitchText(self.TextTitle, 2)
    end

    if cellData.status == JapaneseStoryConstants.QuestStatus.LOCK then
        CfUtils.SetActive(self.ImgGet, false)
        CfUtils.SetActive(self.ImgLock, true)
        CfUtils.SetActive(self.ImgBattleicon, false)
        CfUtils.SetUISwitchText(self.TextTitle, isSelected and 1 or 3)
        CfUtils.SetActive(self.TxtNum, false)
    elseif cellData.status == JapaneseStoryConstants.QuestStatus.NOW then
        CfUtils.SetActive(self.ImgGet, false)
        CfUtils.SetActive(self.ImgLock, false)
        CfUtils.SetActive(self.ImgBattleicon, isSelected)
        CfUtils.SetActive(self.TxtNum, true)
    elseif cellData.status == JapaneseStoryConstants.QuestStatus.PASS then
        CfUtils.SetActive(self.ImgGet, true)
        CfUtils.SetActive(self.ImgLock, false)
        CfUtils.SetActive(self.ImgBattleicon, false)
        CfUtils.SetActive(self.TxtNum, true)
    end

    if cellData.type == JapaneseStoryConstants.QuestPlotType.CARD then
        CfUtils.FillText(self.TxtDeco, 'Card')
        CfUtils.SetActive(self.ImgIcon, true)
        CfUtils.SetUISwitchImage(self.ImgIcon, 1)
    elseif cellData.type == JapaneseStoryConstants.QuestPlotType.BATTLE then
        CfUtils.FillText(self.TxtDeco, 'Battle')
        CfUtils.SetActive(self.ImgIcon, true)
        CfUtils.SetUISwitchImage(self.ImgIcon, 2)
    elseif cellData.type == JapaneseStoryConstants.QuestPlotType.STORY then
        CfUtils.FillText(self.TxtDeco, 'Story')
        CfUtils.SetActive(self.ImgIcon, false)
    end
    
    CfUtils.FillText(self.TxtNum, cellData.levelName)
    CfUtils.FillText(self.TextTitle, cellData.name)
end
--endregion private

